// Prime Directive Compliance Processing for Crew Memories
const memory = $input.first().json.body;

// Extract and process crew memory data
const processedMemory = {
  id: memory.id || `MEMORY_${Date.now()}_${Math.random().toString(36).substr(2, 9)}`,
  timestamp: new Date().toISOString(),
  crew_member: memory.crewMember,
  crew_member_name: getCrewMemberName(memory.crewMember),
  knowledge_type: memory.knowledgeType,
  priority: memory.priority,

  // Core Knowledge Content (Prime Directive Compliant)
  title: memory.title,
  summary: memory.summary,
  detailed_analysis: generalizeContent(memory.detailedAnalysis || ''),
  key_findings: Array.isArray(memory.keyFindings) ? memory.keyFindings : [memory.keyFindings],
  conclusions: Array.isArray(memory.conclusions) ? memory.conclusions : [memory.conclusions],
  recommendations: Array.isArray(memory.recommendations) ? memory.recommendations : [memory.recommendations],

  // Reference Information (Prime Directive Compliant)
  referenced_documents: extractReferences(memory.detailedAnalysis || ''),
  related_topics: memory.tags || [],
  applicable_scenarios: extractApplicableScenarios(memory.detailedAnalysis || ''),
  general_principles: extractGeneralPrinciples(memory.detailedAnalysis || ''),

  // Technical Metadata
  tags: memory.tags || [],
  keywords: extractKeywords(memory.detailedAnalysis || ''),
  complexity_level: calculateComplexityLevel(memory.detailedAnalysis || ''),
  confidence_level: calculateConfidenceLevel(memory.crewMember, memory.knowledgeType),

  // Prime Directive Compliance
  prime_directive_compliance: 'compliant',
  ambiguity_level: 7, // High ambiguity for general principles
  project_specificity: false, // Always false for general principles

  // Semantic Content for Vector Embedding
  semantic_text: generateSemanticText(memory),

  // Collaboration Metadata
  validated_by: [],
  conflict_resolutions: [],

  // Storage Metadata
  storage_timestamp: new Date().toISOString(),
  last_accessed: new Date().toISOString(),
  access_count: 0
};

// Helper Functions
function getCrewMemberName(crewMember) {
  const crewNames = {
    'picard': 'Captain Jean-Luc Picard',
    'riker': 'Commander William Riker',
    'data': 'Commander Data',
    'la_forge': 'Lieutenant Commander Geordi La Forge',
    'worf': 'Lieutenant Worf',
    'troi': 'Counselor Deanna Troi',
    'crusher': 'Dr. Beverly Crusher',
    'uhura': 'Lieutenant Uhura',
    'quark': 'Quark'
  };
  return crewNames[crewMember] || 'Unknown Crew Member';
}

function generalizeContent(text) {
  // Remove project-specific details and generalize
  return text
    .replace(/\b[A-Z]{2,}_[A-Z0-9_]+\b/g, '[PROJECT_REFERENCE]')
    .replace(/\b\d{4}-\d{2}-\d{2}\b/g, '[DATE_REFERENCE]')
    .replace(/\b[a-f0-9]{8}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{12}\b/gi, '[ID_REFERENCE]')
    .replace(/\b[a-z]+-ai-[a-z]+\b/g, '[SYSTEM_REFERENCE]')
    .replace(/\b\/Users\/[^/\s]+\b/g, '[PATH_REFERENCE]');
}

function extractReferences(text) {
  const references = [];

  // Extract URLs
  const urlRegex = /https?:\/\/[^\s]+/g;
  const urls = text.match(urlRegex);
  if (urls) references.push(...urls);

  // Extract documentation references
  const docRegex = /(?:see|refer to|according to|documented in|based on)\s+([^.!?]+)/gi;
  const docMatches = text.match(docRegex);
  if (docMatches) references.push(...docMatches);

  // Extract tool/library references
  const toolRegex = /(?:using|with|via|through)\s+([A-Za-z0-9_-]+(?:\.[a-z]+)?)/gi;
  const toolMatches = text.match(toolRegex);
  if (toolMatches) references.push(...toolMatches);

  return [...new Set(references)]; // Remove duplicates
}

function extractApplicableScenarios(text) {
  const scenarios = [];

  // Extract scenario patterns
  const scenarioRegex = /(?:when|if|in case of|during|while)\s+([^.!?]+)/gi;
  const matches = text.match(scenarioRegex);
  if (matches) {
    scenarios.push(...matches.map(match => match.replace(/^(?:when|if|in case of|during|while)\s+/i, '')));
  }

  return scenarios.slice(0, 5); // Limit to 5 scenarios
}

function extractGeneralPrinciples(text) {
  const principles = [];

  // Extract "always", "never", "should", "must" statements
  const principleRegex = /(?:always|never|should|must|generally|typically|usually|best practice|principle)\s+([^.!?]+)/gi;
  const matches = text.match(principleRegex);
  if (matches) principles.push(...matches);

  // Extract "it is important to" statements
  const importanceRegex = /it is important to\s+([^.!?]+)/gi;
  const importanceMatches = text.match(importanceRegex);
  if (importanceMatches) principles.push(...importanceMatches);

  return principles.slice(0, 10); // Limit to 10 principles
}

function extractKeywords(text) {
  const words = text.toLowerCase().split(/\W+/);
  const stopWords = new Set(['the', 'a', 'an', 'and', 'or', 'but', 'in', 'on', 'at', 'to', 'for', 'of', 'with', 'by', 'is', 'are', 'was', 'were', 'be', 'been', 'being', 'have', 'has', 'had', 'do', 'does', 'did', 'will', 'would', 'could', 'should']);

  const wordCount = new Map();
  words.forEach(word => {
    if (word.length > 3 && !stopWords.has(word)) {
      wordCount.set(word, (wordCount.get(word) || 0) + 1);
    }
  });

  return Array.from(wordCount.entries())
    .sort((a, b) => b[1] - a[1])
    .slice(0, 15)
    .map(([word]) => word);
}

function calculateComplexityLevel(text) {
  const technicalTerms = ['algorithm', 'optimization', 'architecture', 'implementation', 'configuration', 'integration', 'deployment', 'monitoring', 'analysis', 'framework'];
  const technicalCount = technicalTerms.filter(term => text.toLowerCase().includes(term)).length;
  const lengthFactor = Math.min(text.length / 1000, 10);

  return Math.min(10, Math.max(1, Math.round(technicalCount + lengthFactor)));
}

function calculateConfidenceLevel(crewMember, knowledgeType) {
  const expertiseMatrix = {
    'picard': { 'strategic_assessment': 95, 'mission_continuity': 95, 'crew_coordination': 90 },
    'riker': { 'tactical_operations': 95, 'workflow_management': 95, 'team_coordination': 90 },
    'data': { 'technical_analysis': 95, 'logical_assessment': 95, 'system_optimization': 90 },
    'la_forge': { 'infrastructure_health': 95, 'system_monitoring': 95, 'preventive_maintenance': 90 },
    'worf': { 'security_analysis': 95, 'threat_assessment': 95, 'defensive_strategies': 90 },
    'troi': { 'user_experience': 95, 'psychological_assessment': 95, 'communication_optimization': 90 },
    'crusher': { 'system_health': 95, 'medical_diagnosis': 95, 'preventive_care': 90 },
    'uhura': { 'communication_systems': 95, 'data_transmission': 95, 'network_optimization': 90 },
    'quark': { 'business_optimization': 95, 'cost_analysis': 95, 'efficiency_metrics': 90 }
  };

  const crewExpertise = expertiseMatrix[crewMember] || {};
  const typeMatch = Object.keys(crewExpertise).find(expertise => 
    knowledgeType.toLowerCase().includes(expertise.split('_')[0])
  );

  return typeMatch ? crewExpertise[typeMatch] : 75;
}

function generateSemanticText(memory) {
  return `
    ${memory.title}. ${memory.summary}. 
    Crew Member: ${getCrewMemberName(memory.crewMember)}. 
    Knowledge Type: ${memory.knowledgeType}. 
    Key Findings: ${Array.isArray(memory.keyFindings) ? memory.keyFindings.join(', ') : memory.keyFindings}. 
    Conclusions: ${Array.isArray(memory.conclusions) ? memory.conclusions.join(', ') : memory.conclusions}. 
    Recommendations: ${Array.isArray(memory.recommendations) ? memory.recommendations.join(', ') : memory.recommendations}. 
    General Principles: ${extractGeneralPrinciples(memory.detailedAnalysis || '').join(', ')}. 
    Referenced Documents: ${extractReferences(memory.detailedAnalysis || '').join(', ')}. 
    Applicable Scenarios: ${extractApplicableScenarios(memory.detailedAnalysis || '').join(', ')}.
  `.trim();
}

return {
  json: {
    ...processedMemory,
    vector_embedding_ready: true,
    prime_directive_status: 'compliant',
    processing_timestamp: new Date().toISOString()
  }
};

// Crew Memory Storage Success Report
const memory = $input.first().json;

const successReport = {
  report_id: `CREW_MEMORY_REPORT_${Date.now()}`,
  timestamp: new Date().toISOString(),
  crew: memory.crew_member_name,
  report_type: 'crew_memory_storage_success',
  memory_id: memory.id,

  storage_status: {
    supabase_storage: 'successful',
    vector_embedding: 'generated',
    prime_directive_compliance: 'maintained',
    knowledge_type: memory.knowledge_type,
    confidence_level: memory.confidence_level
  },

  prime_directive_validation: {
    project_specificity_removed: true,
    general_principles_extracted: memory.general_principles.length,
    references_documented: memory.referenced_documents.length,
    applicable_scenarios_identified: memory.applicable_scenarios.length,
    ambiguity_level: memory.ambiguity_level
  },

  knowledge_contributions: {
    key_findings: memory.key_findings.length,
    conclusions: memory.conclusions.length,
    recommendations: memory.recommendations.length,
    general_principles: memory.general_principles.length,
    complexity_level: memory.complexity_level
  },

  integration_status: {
    library_computer_access: 'enabled',
    semantic_search: 'available',
    crew_validation: 'ready',
    collective_intelligence: 'updated'
  },

  next_steps: [
    'Memory available for semantic search across crew',
    'Ready for validation by other crew members',
    'Contributing to collective intelligence database',
    'General principles available for future reference'
  ],

  crew_notes: `Crew memory successfully stored in Library Computer with full Prime Directive compliance. Knowledge has been generalized to applicable principles while preserving technical accuracy and crew expertise. Memory is now available for semantic search and collective intelligence enhancement.`
};

return {
  json: successReport
};
